def kernel(x):
    M, N = x.shape
    result = np.empty(M, dtype=np.float32)
    tile_rows = 128
    tile_cols = 512

    for i in range(0, M, tile_rows):
        for j in range(0, N, tile_cols):
            end_i = min(i + tile_rows, M)
            end_j = min(j + tile_cols, N)
            tile = x[i:end_i, j:end_j]

            for row_idx in range(tile.shape[0]):
                row = tile[row_idx]
                max_val = row[0]
                for val in row[1:]:
                    if val > max_val:
                        max_val = val
                # Correctly map the row index from the tile to the global result
                result[i + row_idx] = max_val

    return result

